('vistas-reales', 'Vistas Reales: comer mientras los peques están en la granja', 'Finca de más de 10 hectáreas con restaurante. Los niños dan de comer a los animales, ven vuelo de aves rapaces y hacen juegos de naturaleza con monitores mientras los padres comen. Pases: Explorador (11:00-14:45, 15 €/persona desde 2 años, comida aparte), Mediodía (13:00-17:30) y Aventura (11:00-17:30). Bautismo hípico 8 €.', 'permanente', 'restaurante', null, null, array[6,7]::int[], 'Pases de 11:00 a 17:30; restaurante turnos 13:00 y 15:00', 2, 12, 'exterior', 'Pase Explorador 15 €; menores de 2 gratis; menú aparte', false, 'Soto del Real', 'Cañada de los Rancajales s/n, Soto del Real', 40.7395, -3.765, 'https://www.vistasreales.es/', 'okdiario / elblogdeceleste', true, true),
('burrolandia', 'Burrolandia: dar de comer a burros rescatados', 'Refugio de burros rescatados donde los niños pueden acariciarlos y darles de comer. Solo domingos, gratis con reserva (las plazas vuelan: se abren la noche del domingo anterior).', 'permanente', 'granja', null, null, array[7]::int[], 'Domingos 10:00-12:00 y 12:30-14:30', 0, 12, 'exterior', 'Gratis (donativo recomendado)', true, 'Tres Cantos', 'Camino de la Moraleja 147, Tres Cantos', 40.5795, -3.683, 'https://burrolandiaoficial.es/', 'Time Out', true, true),
('torreon-el-pardo', 'El Torreón de El Pardo: restaurante con parque y granjita', 'Restaurante de El Pardo con parque infantil y una pequeña granja de animales. Buen plan de comida familiar combinado con paseo por el monte de El Pardo.', 'permanente', 'restaurante', null, null, null, 'Horario de restaurante', 0, 10, 'mixto', 'Precio de restaurante', false, 'Madrid (El Pardo)', 'Pista del Cristo de El Pardo 3, Madrid', 40.5245, -3.7735, null, 'myfamilytime / gastroranking', true, false),
('granja-de-los-cuentos-fuenlabrada', 'La Granja de los Cuentos', 'Mañana de sábado en una granja urbana con animales, actividades y desayuno casero incluido. Sesión de 4 horas.', 'permanente', 'granja', null, null, array[6]::int[], 'Sábados 10:00-14:00', 1, 10, 'mixto', 'Niños 25 €, adultos 27 €, bebés <12 meses gratis', false, 'Fuenlabrada', 'C/ Villa Claudia 2, Fuenlabrada', 40.287, -3.8085, null, 'Que Hacer con los Niños', true, true),
